import re, xml.etree.ElementTree as ET
src=open('pelican.html').read()
svg=re.search(r'<svg.*?</svg>', src, re.S).group(0)
root=ET.fromstring(svg)
def local(t): return t.split('}')[-1]
bad=0; n=0
for el in root.iter():
    if local(el.tag) in ('animate','animateTransform','animateMotion'):
        n+=1
        vals=[v.strip() for v in el.get('values','').split(';')]
        kt=el.get('keyTimes')
        if kt:
            kts=kt.split(';')
            if len(kts)!=len(vals): bad+=1; print("MISMATCH", local(el.tag), len(vals), len(kts))
        if el.get('attributeName')=='d':
            structs={tuple(re.findall(r'[A-Za-z]', v)) for v in vals}
            if len(structs)>1: bad+=1; print("d structure mismatch", structs)
            counts={v.count('L')+v.count('M') for v in vals}
            if len(counts)>1: bad+=1; print("d point count mismatch", counts)
print("animation elements:", n, "problems:", bad)
# geometry sanity: leg keyframe endpoints must sit on the crank circle
import math
hip=(335,228); BB=(360,294); r=22; L1,L2=46,50
for el in root.iter():
    if local(el.tag)=='animate' and el.get('attributeName')=='d' and 'M335 228' in el.get('values',''):
        for v in el.get('values').split(';'):
            pts=[tuple(map(float,p.split())) for p in v.split('L')]
            knee,pedal=pts[1],pts[2]
            d1=math.dist(hip,knee); d2=math.dist(knee,pedal); dp=math.dist(BB,pedal)
            if abs(d1-L1)>0.3 or abs(d2-L2)>0.3 or abs(dp-r)>0.3:
                print("IK drift", v, round(d1,1), round(d2,1), round(dp,1))
print("IK check done")
